   391|                    <td>$12,000 - $20,000</td>
   392|                    <td>Same as USA</td>
   393|                    <td>No travel needed</td>
   394|                </tr>
   395|                <tr>
   396|                    <td><strong>Turkey</strong></td>
   397|                    <td>$2,000 - $3,800</td>
   398|                    <td>80-85%</td>
   399|                    <td>Established tourism infrastructure</td>
   400|                </tr>
   401|                <tr>
   402|                    <td><strong>India</strong></td>
   403|                    <td>$1,300 - $2,700</td>
   404|                    <td>85-90%</td>
   405|                    <td>Very low costs</td>
   406|                </tr>
   407|                <tr>
   408|                    <td><strong>China</strong></td>
   409|                    <td>$1,500 - $4,000</td>
   410|                    <td>75-85%</td>
   411|                    <td>Advanced tech + hospital-grade safety</td>
   412|                </tr>
   413|            </tbody>
   414|        </table>
